#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct BIT {
    vector<ll> tr;
    BIT(int n) : tr(n + 1) {}
    void add(int k, ll x) {
        while(k < tr.size()) {
            tr[k] += x;
            k += k&-k;
        }
    }
    ll sum(int k) {
        ll res = 0;
        while(k > 0) {
            res += tr[k];
            k -= k&-k;
        }
        return res;
    }
};

void tc() {
    int n; cin >> n;
    vector<int> a(n), p(n);
    for(int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for(int i = 0; i < n; i++) {
        cin >> p[i]; p[i]--;
    }
    reverse(p.begin(), p.end());
    BIT bit(n);
    set<int> imp; 
    vector<int> ans(n);
    for(int i = 0; i < n; i++) {
        int k = p[i];
        auto it = imp.upper_bound(k);
        int pimp;
        if(it == imp.begin() || bit.sum(k) - bit.sum(*prev(it)) < a[k]) {
            imp.insert(k);
            pimp = k;
        } else {
            pimp = *prev(it);
        }
        bit.add(k + 1, a[k]);
        while(imp.upper_bound(k) != imp.end()) {
            int j = *imp.upper_bound(k);
            if(bit.sum(j) - bit.sum(pimp) >= a[j]) {
                imp.erase(j);
            } else {
                break;
            }
        }
        ans[i] = imp.size() - 1;
    }
    reverse(ans.begin(), ans.end());
    for(int i : ans) cout << i << " ";
    cout << endl;
}

