const int MOD = 1e9 + 7;

void tc() {
    int n; cin >> n;
    vector<ll> a(n);
    for(int i = 0; i < n; i++) cin >> a[i];
    int k = n / 2;

    int val = 1;
    for(int i = 1; i <= k; i++) {
        val = (ll)i * val % MOD;
    }
    for(int i = 1; i <= k - (n % 2 == 0 ? 2 : 1); i++) {
        val = (ll)i * val % MOD;
    }

    set<ll> xposs;
    xposs.insert(a[n - 1] - a[n - 2]);
    xposs.insert(a[n - 1] - a[n - 3]);

    int ans = 0;
    for(ll x : xposs) {
        vector<ll> b;
        for(int i = 0; i < k; i++) {
            b.push_back(i * x);
        }
        for(int i = 0; i < n - k; i++) {
            b.push_back(a[n - 1] - i * x);
        }
        sort(b.begin(), b.end());
        if(a == b) {
            ans += val;
            if(ans >= MOD) ans -= MOD;
        }
    }
    cout << ans << endl;
}

