#include <bits/stdc++.h>
using namespace std;

const int MXN = 400;

template<size_t SZ> int compute_inv(const vector<bitset<SZ>>& mat, vector<bitset<SZ>>& inv) {
    int n = mat.size();
    vector<bool> empty(n, true);
    vector<bitset<SZ>> basis(n);

    for(int i = 0; i < n; i++) {
        bitset<SZ> cur = mat[i];
        bitset<SZ> curinv;
        curinv[i] = 1;
        for(int j = 0; j < n; j++) {
            if(cur[j]) {
                if(empty[j]) {
                    basis[j] = cur;
                    inv[j] = curinv;
                    empty[j] = false;
                    break;
                } else {
                    cur ^= basis[j];
                    curinv ^= inv[j];
                }
            }
        }
    }
    for(int i = 0; i < n; i++) {
        if(empty[i]) return 0;
    }

    for(int i = n - 1; i >= 1; i--) {
        for(int j = 0; j < i; j++) {
            if(basis[j][i]) {
                basis[j] ^= basis[i];
                inv[j] ^= inv[i];
            }
        }
    }
    return 1;
}

bool try_removal(vector<pair<int, int>> cells, vector<bitset<MXN>>& mat, vector<bitset<MXN>>& inv, vector<int>& row_cnt) {
    int n = mat.size(), k = cells.size();
    for(auto [x, y] : cells) {
        if(mat[x][y] == 0) {
            return false;
        }
    }
    assert(k < 4);
    vector<bitset<3>> K(k); 
    for(int i = 0; i < k; i++) {
        for(int j = 0; j < k; j++) {
            K[i][j] = (i == j) ^ inv[cells[i].second][cells[j].first];
        }
    }
    vector<bitset<3>> invK(cells.size());
    if(!compute_inv(K, invK)) {
        return false;
    }
    for(auto [x, y] : cells) {
        mat[x][y] = 0;
        row_cnt[x]--;
    }

    auto old = inv;
    for(int i = 0; i < n; i++) {
        bitset<3> coef;
        for(int alpha = 0; alpha < k; alpha++) {
            int r = cells[alpha].first;

            if(old[i][r]) {
                coef ^= invK[alpha];
            }
        }

        // delta = coef * (V^T * old)
        for(int beta = 0; beta < k; beta++) {
            if(coef[beta]) {
                int c = cells[beta].second;
                inv[i] ^= old[c];
            }
        }
    }
    return true;
}

vector<int> compute_matching(const vector<bitset<MXN>>& mat) {
    int n = mat.size();
    vector<vector<int>> adj(n);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(mat[i][j]) adj[i].push_back(j);
        }
    }

    vector<int> match(n, -1);
    vector<bool> done(n);

    function<bool(int)> dfs = [&] (int s) {
        for(int u : adj[s]) {
            if(!done[u]) {
                done[u] = true;

                if(match[u] == -1 || dfs(match[u])) {
                    match[u] = s;
                    return true;
                }
            }
        }
        return false;
    };

    for(int i = 0; i < n; i++) {
        fill(done.begin(), done.end(), false);
        dfs(i);
    }

    for(int i = 0; i < n; i++) {
        assert(match[i] != -1);
    }
    return match;
}

void tc() {
    int n, m; cin >> n >> m;

    vector<bitset<MXN>> mat(n);
    vector<int> row_cnt(n);
    for(int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        x--, y--;
        mat[x][y] = 1;
        row_cnt[x]++;
    }

    vector<bitset<MXN>> inv(n);
    compute_inv(mat, inv);

    int sm = m;
    int left = (sm + n - 1) / n;
    cout << left << '\n';

    while(sm > 0) {
        vector<bitset<MXN>> omat = mat;
        if(sm <= n) {
            for(int i = 0; i < n; i++) {
                for(int j = 0; j < n; j++) {
                    mat[i][j] = 0;
                }
            }
            row_cnt.assign(n, 0);
        } else if(sm <= 2 * n) {
            vector<int> matching = compute_matching(mat);
            for(int i = 0; i < n; i++) {
                for(int j = 0; j < n; j++) {
                    mat[i][j] = 0;
                }
            }
            row_cnt.assign(n, 0);
            for(int i = 0; i < sm - n; i++) {
                mat[matching[i]][i] = 1;
                row_cnt[matching[i]]++;
            }
        } else if(sm <= 3 * n) {
            vector<int> matching = compute_matching(mat);
            int above = 0;
            for(int i = 0; i < n; i++) {
                for(int j = matching[i] + 1; j < n; j++) {
                    above += mat[j][i];
                }
            }

            vector<bitset<MXN>> nmat(n);
            vector<int> nrow_cnt(n);
            int ones_left = sm - n;
            for(int i = 0; i < n; i++) {
                nmat[matching[i]][i] = 1;
                nrow_cnt[matching[i]]++;
                ones_left--;
            }
            // make matrix either upper or lower triangular, whichever one
            // removes a sufficient number of ones
            if(above >= ones_left) {
                for(int i = 0; i < n; i++) {
                    for(int j = matching[i] + 1; j < n; j++) {
                        if(mat[j][i]) {
                            ones_left--;
                            nmat[j][i] = 1;
                            nrow_cnt[j]++;
                            if(ones_left == 0) break;
                        }
                    }
                    if(ones_left == 0) break;
                }
            } else {
                for(int i = 0; i < n; i++) {
                    for(int j = 0; j < matching[i]; j++) {
                        if(mat[j][i]) {
                            ones_left--;
                            nmat[j][i] = 1;
                            nrow_cnt[j]++;
                            if(ones_left == 0) break;
                        }
                    }
                    if(ones_left == 0) break;
                }
            }
            mat = nmat;
            row_cnt = nrow_cnt;
        } else {
            int csm = sm;
            if(n % 2) {
                // odd case (remove either 1 or 3)
                int dup_row = -1;
                for(int i = 0; i < n; i++) {
                    if(row_cnt[i] >= 2) {
                        dup_row = i;
                        break;
                    }
                }
                assert(dup_row != -1);

                vector<int> cols;
                for(int i = 0; i < n; i++) {
                    if(mat[dup_row][i]) cols.push_back(i);
                }

                assert(cols.size() >= 2);

                for(int i = 0; i < n; i++) {
                    if(try_removal({{i, cols[0]}}, mat, inv, row_cnt)) {
                        csm--;
                        break;
                    }
                    if(try_removal({{i, cols[1]}}, mat, inv, row_cnt)) {
                        csm--;
                        break;
                    }
                }

                if(csm == sm) {
                    for(int i = 0; i < n; i++) {
                        if(i != dup_row) {
                            // remove L shape
                            if(try_removal(
                                    {{i, cols[0]}, 
                                     {dup_row, cols[0]}, 
                                     {dup_row, cols[1]}},
                                mat, inv, row_cnt)) {
                                csm -= 3;
                                break;
                            }
                        }
                    }
                    assert(sm != csm);
                }
            }

            while(csm > sm - n) {
                // remove 2 at a time
                int dup_row = -1;
                for(int i = 0; i < n; i++) {
                    if(row_cnt[i] >= 3) {
                        dup_row = i;
                        break;
                    }
                }

                vector<int> cols;
                for(int i = 0; i < n; i++) {
                    if(mat[dup_row][i]) cols.push_back(i);
                }

                assert(cols.size() >= 3);

                if(!try_removal({{dup_row, cols[0]}, {dup_row, cols[1]}}, mat, inv, row_cnt)) {
                    if(!try_removal({{dup_row, cols[1]}, {dup_row, cols[2]}}, mat, inv, row_cnt)) {
                        if(!try_removal({{dup_row, cols[0]}, {dup_row, cols[2]}}, mat, inv, row_cnt)) {
                            assert(false);
                        }
                    }
                }

                csm -= 2;
            }
            assert(csm == sm - n);
        }

        vector<pair<int, int>> move;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(omat[i][j] == 1 && mat[i][j] == 0) {
                    move.push_back({i, j});
                }
            }
        }
        cout << move.size() << "\n";
        for(auto [x, y] : move) cout << x + 1 << " " << y + 1 << "\n";
        sm -= n;

        int csm = 0;
        for(int i = 0; i < n; i++) {
            csm += row_cnt[i];
        }
        assert(csm == max(0, sm));
    }
}

int main() {
    int t; cin >> t;
    while(t--) tc();
}

#include <bits/stdc++.h>
using namespace std;

const int SZ = 400;


template<size_t SZ> int compute_inv(const vector<bitset<SZ>>& mat, vector<bitset<SZ>>& inv) {
    int n = mat.size();
    vector<bool> empty(n, true);
    vector<bitset<SZ>> basis(n);

    for(int i = 0; i < n; i++) {
        bitset<SZ> cur = mat[i];
        bitset<SZ> curinv;
        curinv[i] = 1;
        for(int j = 0; j < n; j++) {
            if(cur[j]) {
                if(empty[j]) {
                    basis[j] = cur;
                    inv[j] = curinv;
                    empty[j] = false;
                    break;
                } else {
                    cur ^= basis[j];
                    curinv ^= inv[j];
                }
            }
        }
    }
    for(int i = 0; i < n; i++) {
        if(empty[i]) return 0;
    }

    for(int i = n - 1; i >= 1; i--) {
        for(int j = 0; j < i; j++) {
            if(basis[j][i]) {
                basis[j] ^= basis[i];
                inv[j] ^= inv[i];
            }
        }
    }
    return 1;
}

void tc() {
    int n, m; cin >> n >> m;
    vector<bitset<SZ>> mat(n);
    for(int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        x--, y--;
        mat[x][y] = 1;
    }

    vector<bitset<SZ>> inv(n);
    compute_inv(mat, inv);
    vector<int> cnts(2 * n);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            cnts[i] += mat[i][j];
            cnts[n + j] += mat[i][j];
        }
    }
    queue<pair<int, int>> mustq, freeq;
    vector<pair<int, int>> centers;
    vector<vector<pair<int, int>>> moves;
    while(true) {
        while(mustq.size() + freeq.size() < n) {
            int best_rc = 0;
            for(int rc = 0; rc < 2 * n; rc++) {
                if(cnts[rc] >= cnts[best_rc]) best_rc = rc;
            }
            if(cnts[best_rc] == 0) {
                break;
            }

            int x = -1, y = -1;
            if(best_rc < n) {
                x = best_rc;
                for(int j = 0; j < n; j++) {
                    if(mat[x][j] && inv[j][x]) {
                        y = j;
                        break;
                    }
                }
            } else {
                y = best_rc - n;
                for(int j = 0; j < n; j++) {
                    if(mat[j][y] && inv[y][j]) {
                        x = j;
                        break;
                    }
                }
            }
            assert(x != -1 && y != -1);

            centers.push_back({x, y});
            vector<pair<int, int>> must, free;
            auto erase = [&] (int a, int b) {
                mat[a][b] = 0;
                cnts[a]--;
                cnts[b + n]--;
            };
            for(int j = 0; j < n; j++) {
                if(mat[x][j] && j != y) {
                    must.push_back({x, j});
                    erase(x, j);
                }
            }
            for(int j = 0; j < n; j++) {
                if(mat[j][y] && j != x) {
                    free.push_back({j, y});
                    erase(j, y);
                }
            }
            erase(x, y);
            assert(cnts[x] == 0 && cnts[n + y] == 0);

            if(best_rc < n) swap(must, free);
            for(auto u : must) mustq.push(u);
            for(auto u : free) freeq.push(u);

            bitset<SZ> row = inv[y];
            for(int j = 0; j < n; j++) {
                if(cnts[j + n] > 0 && inv[j][x]) {
                    inv[j] ^= row;
                }
            }
        }
        int left = n;
        vector<pair<int, int>> move;
        while(left > 0 && mustq.size() > 0) {
            left--;
            move.push_back(mustq.front());
            mustq.pop();
        }
        while(left > 0 && freeq.size() > 0) {
            left--;
            move.push_back(freeq.front());
            freeq.pop();
        }
        while(left > 0 && centers.size() > 0) {
            left--;
            move.push_back(centers.back());
            centers.pop_back();
        }
        moves.push_back(move);
        if(centers.size() == 0) break;
    }
    cout << moves.size() << "\n";
    for(auto move : moves) {
        cout << move.size() << "\n";
        for(auto [u, v] : move) cout << u + 1 << " " << v + 1 << "\n";
    }
}

int main() {
    ios::sync_with_stdio(false), cin.tie(nullptr);
    int t; cin >> t;
    while(t--) tc();
}
